import * as THREE from 'three';
import Ajax from 'core/ajax';
import Notification from 'core/notification';
import Str from 'core/str';

/* global Peer */

/**
 * SyncManager class for collaborative mode & WebRTC.
 */
export default class SyncManager {
    constructor(viewer) {
        this.viewer = viewer;
        this.interval = null;
        this.avatars = {}; // Map of userid -> { mesh }
        this.lastPosition = null;
        this.lastRotation = null;

        // WebRTC
        this.peer = null;
        this.localStream = null;
        this.calls = {}; // PeerId -> call
        this.dataConns = {}; // PeerId -> dataConn
        this.voiceEnabled = false;

        // Live classroom: 3D Laser Pointer & Follow Presenter.
        this.laserMarkers = {}; // PeerId -> { mesh, timer }
        this.lastLaserSent = 0;
        this.laserActive = false;
        this.broadcastingView = false;
        this.followingPresenter = false;
        this.inkMode = false;
        this.inkDrawing = false;
        this.inkPoints = [];
        this.inkLines = [];
        this.currentInkLine = null;
        this.broadcastInterval = null;
        this.onLaserPointerMove = (e) => this.handleLaserMove(e);
        this.onInkDown = (e) => this.handleInkDown(e);
        this.onInkMove = (e) => this.handleInkMove(e);
        this.onInkUp = () => this.handleInkUp();
        this.onLaserKeyUp = (e) => {
            if (e.key === 'Alt' && this.laserActive) {
                this.laserActive = false;
                this.broadcastData({type: 'laser', active: false});
            }
        };

        // Random id of this browser session. The server lists the participants and only those peers are accepted.
        var bytes = new Uint8Array(12);
        window.crypto.getRandomValues(bytes);
        this.peerId = 'gear' + Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
        this.known = {}; // PeerId -> userid of the current participants.
    }

    /**
     * Whether a peer is a participant of this session. Unknown peers get one fresh look at the session list.
     *
     * @param {string} peerId Peer id
     * @returns {Promise<boolean>}
     */
    async acceptPeer(peerId) {
        if (this.known[peerId]) {
            return true;
        }
        await this.sync();
        return !!this.known[peerId];
    }

    initPeer() {
        if (!this.peerPromise) {
            this.peerPromise = this.createPeer();
        }
        return this.peerPromise;
    }

    async createPeer() {
        if (this.peer) {
            return;
        }
        try {
            await this.loadPeerJs();
        } catch (e) {
            this.peerPromise = null;
            return;
        }
        this.peer = new Peer(this.peerId, this.viewer.peerServer || {});

        this.peer.on('call', async(call) => {
            if (!await this.acceptPeer(call.peer)) {
                call.close();
                return;
            }
            if (this.localStream) {
                call.answer(this.localStream);
            } else {
                call.answer(); // Empty stream
            }
            this.handleCall(call);
        });

        this.peer.on('connection', async(conn) => {
            if (!await this.acceptPeer(conn.peer)) {
                conn.close();
                return;
            }
            this.handleDataConnection(conn);
        });
    }

    /**
     * Load the self-hosted PeerJS script on first use (it is only needed when several people share a session).
     *
     * @returns {Promise<void>}
     */
    loadPeerJs() {
        if (typeof Peer !== 'undefined') {
            return Promise.resolve();
        }
        return new Promise((resolve, reject) => {
            var script = document.createElement('script');
            script.src = this.viewer.peerjsUrl;
            script.onload = () => resolve();
            script.onerror = () => reject(new Error('PeerJS failed to load'));
            document.head.appendChild(script);
        });
    }

    async joinVoiceChat() {
        if (this.voiceEnabled) {
 return;
}
        try {
            this.localStream = await navigator.mediaDevices.getUserMedia({audio: true, video: false});
            this.voiceEnabled = true;

            if (!this.peer) {
                await this.initPeer();
            }

            var btn = document.getElementById('gear-voice-btn-' + this.viewer.cmid);
            if (btn) {
                btn.querySelector('i').className = 'fa fa-microphone text-success';
            }

            Notification.addNotification({message: await Str.get_string('voicejoined', 'mod_gear'), type: 'success'});
        } catch (e) {
            Notification.alert(await Str.get_string('error', 'core'), await Str.get_string('voicenotsupported', 'mod_gear'));
        }
    }

    handleCall(call) {
        call.on('stream', (remoteStream) => {
            var peerUserId = this.known[call.peer];

            var avatar = this.avatars[peerUserId];
            // Only attach if avatar exists and doesn't already have audio
            if (avatar && !avatar.hasAudio) {
                var sound = new THREE.PositionalAudio(this.viewer.audioListener);
                // R128 PositionalAudio supports setMediaStreamSource
                if (typeof sound.setMediaStreamSource === 'function') {
                    sound.setMediaStreamSource(remoteStream);
                } else {
                    // Fallback
                    sound.setNodeSource(sound.context.createMediaStreamSource(remoteStream));
                }
                sound.setRefDistance(2);
                avatar.mesh.add(sound);
                avatar.hasAudio = true;
            }
        });
        this.calls[call.peer] = call;
    }

    handleDataConnection(conn) {
        conn.on('open', () => {
            this.dataConns[conn.peer] = conn;
        });
        conn.on('data', async(data) => {
            if (!data || typeof data !== 'object') {
                return;
            }
            if (data.type === 'laser') {
                this.handleRemoteLaser(conn.peer, data);
                return;
            }
            if (data.type === 'presenter_view') {
                this.handleRemotePresenterView(data);
                return;
            }
            if (data.type === 'ink_stroke') {
                this.renderInkStroke(data.points || []);
                return;
            }
            if (data.type === 'ink_clear') {
                this.clearInkStrokes(false);
                return;
            }
            if (typeof data.text !== 'string') {
                return;
            }
            const sender = await Str.get_string('chatuser', 'mod_gear', this.known[conn.peer] || '?');
            this.displayChatMessage(sender, data.text.substring(0, 500), 'other');
        });
        conn.on('close', () => {
            delete this.dataConns[conn.peer];
            this.clearRemoteLaser(conn.peer);
        });
    }

    /**
     * Broadcast a JSON payload to all open peer data connections.
     *
     * @param {Object} payload
     */
    broadcastData(payload) {
        Object.values(this.dataConns).forEach((conn) => {
            if (conn.open) {
                conn.send(payload);
            }
        });
    }

    connectData(peerId) {
        if (this.dataConns[peerId]) {
 return;
}
        var conn = this.peer.connect(peerId);
        this.handleDataConnection(conn);
    }

    sendChatMessage(text) {
        var msg = {text: text};
        Object.values(this.dataConns).forEach(conn => {
            if (conn.open) {
                conn.send(msg);
            }
        });
        Str.get_string('chatme', 'mod_gear').then((me) => this.displayChatMessage(me, text, 'self')).catch(Notification.exception);
    }

    displayChatMessage(sender, text, type) {
        var messagesDiv = document.getElementById('gear-chat-messages-' + this.viewer.cmid);
        if (!messagesDiv) {
 return;
}
        var msgDiv = document.createElement('div');
        msgDiv.className = 'gear-chat-msg ' + type;
        var senderSpan = document.createElement('span');
        senderSpan.className = 'gear-chat-sender';
        senderSpan.textContent = String(sender);
        msgDiv.appendChild(senderSpan);
        msgDiv.appendChild(document.createTextNode(String(text)));
        messagesDiv.appendChild(msgDiv);
        messagesDiv.scrollTop = messagesDiv.scrollHeight;
    }

    start() {
        this.interval = setInterval(() => {
            if (!document.hidden) {
                this.sync();
            }
        }, 2000);
        this.sync(); // Initial call
        this.setupClassroomControls();
    }

    stop() {
        if (this.interval) {
            clearInterval(this.interval);
            this.interval = null;
        }
        if (this.broadcastInterval) {
            clearInterval(this.broadcastInterval);
            this.broadcastInterval = null;
        }
        if (this.viewer.canvas) {
            this.viewer.canvas.removeEventListener('pointermove', this.onLaserPointerMove);
            this.viewer.canvas.removeEventListener('pointerdown', this.onInkDown, true);
            this.viewer.canvas.removeEventListener('pointermove', this.onInkMove, true);
        }
        window.removeEventListener('pointerup', this.onInkUp);
        this.clearInkStrokes(false);
        document.removeEventListener('keyup', this.onLaserKeyUp);
    }

    sync() {
        if (!this.viewer.camera) {
            return Promise.resolve();
        }

        // Use Three.js properties.
        var pos = this.viewer.camera.position;
        var rot = this.viewer.camera.rotation;

        // Only update if changed significantly?
        // For now, send anyway to keep session alive (heartbeat).

        var posObj = {x: pos.x, y: pos.y, z: pos.z};
        var rotObj = {x: rot.x, y: rot.y, z: rot.z}; // Euler

        return Ajax.call([{
            methodname: 'mod_gear_sync_session',
            args: {
                gearid: this.viewer.gearid,
                position: JSON.stringify(posObj),
                rotation: JSON.stringify(rotObj),
                peerid: this.peerId
            }
        }])[0].then((users) => {
            this.updateAvatars(users);
            return users;
        }).catch((e) => {
            window.console.warn('Sync error', e);
        });
    }

    updateAvatars(users) {
        var activeIds = new Set();

        this.known = {};
        users.forEach((user) => {
            activeIds.add(user.userid);
            if (user.peerid) {
                this.known[user.peerid] = user.userid;
            }

            if (!this.avatars[user.userid]) {
                this.createAvatar(user);
            }

            this.updateAvatarState(user);
        });

        // Remove disconnected users.
        Object.keys(this.avatars).forEach((id) => {
            if (!activeIds.has(parseInt(id))) {
                this.removeAvatar(id);
            }
        });

        // Close calls and chat connections of peers that left the session.
        [this.calls, this.dataConns].forEach((map) => {
            Object.keys(map).forEach((peerId) => {
                if (!this.known[peerId]) {
                    if (map[peerId] && map[peerId].close) {
                        map[peerId].close();
                    }
                    delete map[peerId];
                }
            });
        });

        // PeerJS is only needed when somebody else is in the session.
        if (!this.peer && users.some((user) => user.userid != this.viewer.userid)) {
            this.initPeer();
        }

        // Connect uncalled voice peers
        if (this.peer) {
            users.forEach((user) => {
                if (user.userid != this.viewer.userid && user.peerid) {
                    var pId = user.peerid;
                    if (this.voiceEnabled && !this.calls[pId]) {
                        var call = this.peer.call(pId, this.localStream);
                        if (call) {
                            this.handleCall(call);
                        } else {
                            this.calls[pId] = null;
                        }
                    }
                    // Connect text chat
                    if (!this.dataConns[pId]) {
                        this.connectData(pId);
                    }
                }
            });
        }
    }

    createAvatar(user) {
        // Create a group for the avatar.
        var group = new THREE.Group();

        // Simple avatar: Sphere representing head.
        var geometry = new THREE.SphereGeometry(0.3, 16, 16);
        var color = '#' + Math.floor(Math.random() * 16777215).toString(16);
        var material = new THREE.MeshBasicMaterial({color: color});
        var sphere = new THREE.Mesh(geometry, material);
        group.add(sphere);

        // Add to scene.
        this.viewer.scene.add(group);

        this.avatars[user.userid] = {
            mesh: group
        };
    }

    updateAvatarState(user) {
        var avatar = this.avatars[user.userid];
        if (!avatar) {
 return;
}

        if (user.position) {
            try {
                var pos = (typeof user.position === 'string') ? JSON.parse(user.position) : user.position;
                avatar.mesh.position.set(pos.x, pos.y, pos.z);
            } catch (e) {
                // Ignore parse error
            }
        }

        if (user.rotation) {
             try {
                var rot = (typeof user.rotation === 'string') ? JSON.parse(user.rotation) : user.rotation;
                avatar.mesh.rotation.set(rot.x, rot.y, rot.z);
            } catch (e) {
                // Ignore parse error
            }
        }
    }

    removeAvatar(userid) {
        var avatar = this.avatars[userid];
        if (avatar && avatar.mesh) {
            this.viewer.scene.remove(avatar.mesh);
            // Optional: dispose geometry/material.
        }
        delete this.avatars[userid];
    }

    /**
     * Wire 3D Laser Pointer and Broadcast/Follow Presenter controls.
     */
    setupClassroomControls() {
        if (this.viewer.canvas) {
            this.viewer.canvas.addEventListener('pointermove', this.onLaserPointerMove);
        }
        document.addEventListener('keyup', this.onLaserKeyUp);

        const cmid = this.viewer.cmid;
        const broadcastBtn = document.getElementById('gear-broadcast-btn-' + cmid);
        if (broadcastBtn) {
            broadcastBtn.addEventListener('click', () => {
                this.broadcastingView = !this.broadcastingView;
                broadcastBtn.classList.toggle('active', this.broadcastingView);
                broadcastBtn.classList.toggle('btn-primary', this.broadcastingView);
                if (this.broadcastingView) {
                    this.initPeer();
                    this.broadcastInterval = setInterval(() => this.sendPresenterView(), 120);
                } else if (this.broadcastInterval) {
                    clearInterval(this.broadcastInterval);
                    this.broadcastInterval = null;
                }
            });
        }

        const followBtn = document.getElementById('gear-follow-btn-' + cmid);
        if (followBtn) {
            followBtn.addEventListener('click', () => {
                this.followingPresenter = !this.followingPresenter;
                followBtn.classList.toggle('active', this.followingPresenter);
                followBtn.classList.toggle('btn-primary', this.followingPresenter);
                if (this.followingPresenter) {
                    this.initPeer();
                }
            });
        }

        const inkBtn = document.getElementById('gear-ink-btn-' + cmid);
        const inkClearBtn = document.getElementById('gear-ink-clear-btn-' + cmid);
        if (inkBtn) {
            inkBtn.addEventListener('click', () => {
                this.inkMode = !this.inkMode;
                inkBtn.classList.toggle('active', this.inkMode);
                inkBtn.classList.toggle('btn-warning', this.inkMode);
                if (inkClearBtn) {
                    inkClearBtn.classList.toggle('d-none', !this.inkMode && !this.inkLines.length);
                }
                if (this.viewer.controls) {
                    this.viewer.controls.enabled = !this.inkMode;
                }
                if (this.viewer.canvas) {
                    this.viewer.canvas.style.cursor = this.inkMode ? 'crosshair' : 'default';
                    if (this.inkMode) {
                        this.initPeer();
                        this.viewer.canvas.addEventListener('pointerdown', this.onInkDown, true);
                        this.viewer.canvas.addEventListener('pointermove', this.onInkMove, true);
                        window.addEventListener('pointerup', this.onInkUp);
                    } else {
                        this.viewer.canvas.removeEventListener('pointerdown', this.onInkDown, true);
                        this.viewer.canvas.removeEventListener('pointermove', this.onInkMove, true);
                        window.removeEventListener('pointerup', this.onInkUp);
                    }
                }
            });
        }
        if (inkClearBtn) {
            inkClearBtn.addEventListener('click', () => {
                this.clearInkStrokes(true);
                if (!this.inkMode) {
                    inkClearBtn.classList.add('d-none');
                }
            });
        }
    }

    /**
     * Start a 3D surface ink stroke.
     *
     * @param {PointerEvent} event
     */
    handleInkDown(event) {
        if (!this.inkMode || event.button !== 0 || !this.viewer.tools) {
            return;
        }
        const hit = this.viewer.tools.raycastModel(event);
        if (!hit) {
            return;
        }
        event.stopPropagation();
        this.inkDrawing = true;
        const pt = hit.point.clone().addScaledVector(hit.face ? hit.face.normal : new THREE.Vector3(0, 1, 0), 0.01);
        this.inkPoints = [pt];
        const geom = new THREE.BufferGeometry().setFromPoints([pt, pt]);
        const mat = new THREE.LineBasicMaterial({color: 0xfacc15, linewidth: 2});
        this.currentInkLine = new THREE.Line(geom, mat);
        this.viewer.scene.add(this.currentInkLine);
        this.inkLines.push(this.currentInkLine);
    }

    /**
     * Extend active 3D surface ink stroke.
     *
     * @param {PointerEvent} event
     */
    handleInkMove(event) {
        if (!this.inkMode || !this.inkDrawing || !this.currentInkLine || !this.viewer.tools) {
            return;
        }
        const hit = this.viewer.tools.raycastModel(event);
        if (!hit) {
            return;
        }
        const pt = hit.point.clone().addScaledVector(hit.face ? hit.face.normal : new THREE.Vector3(0, 1, 0), 0.01);
        const last = this.inkPoints[this.inkPoints.length - 1];
        if (last && last.distanceToSquared(pt) < 0.0004) {
            return;
        }
        this.inkPoints.push(pt);
        this.currentInkLine.geometry.dispose();
        this.currentInkLine.geometry = new THREE.BufferGeometry().setFromPoints(this.inkPoints);
    }

    /**
     * Finish and broadcast a 3D surface ink stroke.
     */
    handleInkUp() {
        if (!this.inkDrawing) {
            return;
        }
        this.inkDrawing = false;
        this.currentInkLine = null;
        if (this.inkPoints.length >= 2) {
            this.broadcastData({
                type: 'ink_stroke',
                points: this.inkPoints.map((p) => [
                    Math.round(p.x * 1e4) / 1e4,
                    Math.round(p.y * 1e4) / 1e4,
                    Math.round(p.z * 1e4) / 1e4,
                ]),
            });
        }
        this.inkPoints = [];
    }

    /**
     * Render a remote peer's 3D ink stroke.
     *
     * @param {Array} pts Array of [x, y, z]
     */
    renderInkStroke(pts) {
        if (!Array.isArray(pts) || pts.length < 2) {
            return;
        }
        const vecs = pts.map((p) => new THREE.Vector3(p[0], p[1], p[2]));
        const geom = new THREE.BufferGeometry().setFromPoints(vecs);
        const mat = new THREE.LineBasicMaterial({color: 0xfacc15, linewidth: 2});
        const line = new THREE.Line(geom, mat);
        this.viewer.scene.add(line);
        this.inkLines.push(line);
    }

    /**
     * Clear all 3D ink strokes from the scene.
     *
     * @param {boolean} broadcast Whether to notify peers
     */
    clearInkStrokes(broadcast) {
        this.inkLines.forEach((line) => {
            this.viewer.scene.remove(line);
            if (line.geometry) {
                line.geometry.dispose();
            }
            if (line.material) {
                line.material.dispose();
            }
        });
        this.inkLines = [];
        if (broadcast) {
            this.broadcastData({type: 'ink_clear'});
        }
    }

    /**
     * Broadcast 3D laser pointer position when Alt is held.
     *
     * @param {PointerEvent} event
     */
    handleLaserMove(event) {
        if (!event.altKey || !this.viewer.tools) {
            return;
        }
        const now = Date.now();
        if (now - this.lastLaserSent < 50) {
            return;
        }
        const hit = this.viewer.tools.raycastModel(event);
        if (!hit) {
            return;
        }
        this.lastLaserSent = now;
        this.laserActive = true;
        this.initPeer();
        this.broadcastData({
            type: 'laser',
            active: true,
            pos: [hit.point.x, hit.point.y, hit.point.z],
        });
    }

    /**
     * Render or hide a remote peer's 3D laser pointer dot.
     *
     * @param {string} peerId
     * @param {Object} data
     */
    handleRemoteLaser(peerId, data) {
        if (!data.active || !Array.isArray(data.pos) || data.pos.length !== 3) {
            this.clearRemoteLaser(peerId);
            return;
        }
        let entry = this.laserMarkers[peerId];
        if (!entry) {
            const radius = (this.viewer.hotspotScale || 1.0) * 0.045;
            const geom = new THREE.SphereGeometry(radius, 16, 16);
            const mat = new THREE.MeshBasicMaterial({color: 0xff2d55, depthTest: false});
            const mesh = new THREE.Mesh(geom, mat);
            mesh.renderOrder = 998;
            this.viewer.scene.add(mesh);
            entry = {mesh, timer: null};
            this.laserMarkers[peerId] = entry;
        }
        entry.mesh.visible = true;
        entry.mesh.position.set(data.pos[0], data.pos[1], data.pos[2]);
        if (entry.timer) {
            clearTimeout(entry.timer);
        }
        entry.timer = setTimeout(() => this.clearRemoteLaser(peerId), 1500);
    }

    /**
     * Hide/remove a peer's 3D laser marker.
     *
     * @param {string} peerId
     */
    clearRemoteLaser(peerId) {
        const entry = this.laserMarkers[peerId];
        if (!entry) {
            return;
        }
        if (entry.timer) {
            clearTimeout(entry.timer);
        }
        if (entry.mesh) {
            this.viewer.scene.remove(entry.mesh);
            entry.mesh.geometry.dispose();
            entry.mesh.material.dispose();
        }
        delete this.laserMarkers[peerId];
    }

    /**
     * Broadcast presenter camera and explode state to followers.
     */
    sendPresenterView() {
        if (!this.broadcastingView || !this.viewer.camera || !this.viewer.controls) {
            return;
        }
        const cam = this.viewer.camera.position;
        const tgt = this.viewer.controls.target;
        this.broadcastData({
            type: 'presenter_view',
            pos: [cam.x, cam.y, cam.z],
            target: [tgt.x, tgt.y, tgt.z],
            explode: this.viewer.tools ? this.viewer.tools.explodeFactor : 0,
        });
    }

    /**
     * Apply incoming presenter camera and explode state if Follow Presenter is enabled.
     *
     * @param {Object} data
     */
    handleRemotePresenterView(data) {
        if (!this.followingPresenter || !this.viewer.camera || !this.viewer.controls) {
            return;
        }
        if (Array.isArray(data.pos) && data.pos.length === 3) {
            this.viewer.camera.position.lerp(new THREE.Vector3(data.pos[0], data.pos[1], data.pos[2]), 0.35);
        }
        if (Array.isArray(data.target) && data.target.length === 3) {
            this.viewer.controls.target.lerp(new THREE.Vector3(data.target[0], data.target[1], data.target[2]), 0.35);
        }
        this.viewer.controls.update();
        if (typeof data.explode === 'number' && this.viewer.tools) {
            this.viewer.tools.setExplodeFactor(data.explode);
        }
    }
}
